/* From Uiverse.io by adamgiebl - Tags: gradient, card */
.__UIV_SCOPE__ .card {
  position: relative;
  width: 190px;
  height: 254px;
  background: lightgrey;
  box-shadow: #d11bff42 0 15px 40px -5px;
  z-index: 1;
  border-radius: 21px;
  overflow: hidden;
}

.__UIV_SCOPE__ .card__content {
  background: linear-gradient(rgba(255, 255, 255, 0.473), rgba(150, 150, 150, 0.25));
  z-index: 1;
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  border-radius: 21px;
}

.__UIV_SCOPE__ .card .blob {
  position: absolute;
  z-index: -1;
  border-radius: 5em;
  width: 200px;
  height: 200px;
}

.__UIV_SCOPE__ .card .blob:nth-child(2) {
  left: -50px;
  top: -90px;
  background: #ff930f;
}

.__UIV_SCOPE__ .card .blob:nth-child(3) {
  left: 110px;
  top: -20px;
  z-index: -1;
  background: #bf0fff;
}

.__UIV_SCOPE__ .card .blob:nth-child(4) {
  left: -40px;
  top: 100px;
  background: #ff1b6b;
}

.__UIV_SCOPE__ .card .blob:nth-child(5) {
  left: 100px;
  top: 180px;
  background: #0061ff;
}
